import{_ as n,o,c as t,ak as a}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Implementation order","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"Implementation order","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/planning/implementation-plan.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/implementation-plan.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/implementation-plan.md"}'),r={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/implementation-plan.md"};function i(s,e,d,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="implementation-order">Implementation order<a class="header-anchor" href="#implementation-order" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p>Updated October 13, 2026. This is a short reading guide; the card-by-card dependencies live in the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/kanban-plan-draft.html">Kanban/Gantt plan</a>, and bounded AI agent lanes and handoffs live in the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/agentic-parallel-execution-plan.html">parallel execution plan</a>.</p><ol><li><strong>Resolve inputs:</strong> Sherwin records school and design decisions; Christian confirms the real game repository, revision, Unity version and reproducible Android build. Sean turns approved information into project documents.</li><li><strong>Confirm the common interface:</strong> Christian owns the actual SQLite and saved-result implementation contract. Miguel builds only the assigned player-facing screens. Luis supplies art assets through separate cards.</li><li><strong>Prove one mode end to end:</strong> Christian completes the agreed Quiz interaction, local save, close, and reload path before the other modes depend on it.</li><li><strong>Implement the approved scope:</strong> the game has explorable levels with learning interactions plus Quiz, Wordle and BlockMatch. Do not add features beyond Christian&#39;s adopted technical design. Sherwin decides game rules; Christian implements them; Sean writes the documentation after those decisions are approved.</li><li><strong>Integrate and verify:</strong> Christian owns code/build integration. Miguel executes player-screen and device-use checks on assigned cards. Sean records actual evidence and beta documentation. Sherwin coordinates school and team readiness.</li><li><strong>Protect delivery:</strong> preserve the fixed <strong>November 3–6 beta</strong> and <strong>November 21 pre-final</strong>, with the planned October 26–30 integration, October 31–November 2 device checks, and November 17–20 rehearsal. These targets do not prove capacity; each member&#39;s available hours and the working build remain evidence to obtain.</li></ol><p>Only cards with stable inputs and no shared output run in parallel. A cross-role dependency is a handoff, not a co-owned card. If the source, build, scope, school approval, or capacity is missing, record it as a blocker; do not claim readiness from the number of cards.</p></div>',1)])])}const v=n(r,[["render",i]]);export{m as __pageData,v as default};
